{
 "summary": "The main theorem is formalized faithfully. For n ≥ 1, if S ⊂ ℝⁿ is convex and compact, has nonempty interior and barycenter 0, and int(S) ∩ ℤⁿ = {0}, then vol(S) ≤ (n+1)ⁿ/n!. Two companion lemmas compute the barycenter (0) and the volume ((n+1)ⁿ/n!) of the centered simplex (n+1)Δₙ − (1,…,1). The most important caveat is that the sharpness existence theorem `exists_centeredBody_sharp` carries the false hypothesis (1 : ℕ) = 0, so it is vacuous. Also, nothing formalizes that the centered simplex has 0 as its only interior lattice point, so sharpness is not actually established.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ", "standard_concept": "Euclidean space ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.integerPoint", "line": 12, "plain": "embedding ℤⁿ → ℝⁿ", "standard_concept": "lattice point inclusion", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δₙ = {x ≥ 0, Σxᵢ ≤ 1} = conv{0, e₁, …, eₙ}", "standard_concept": "standard simplex Δₙ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+1)x − (1,…,1)", "standard_concept": "affine map defining the centered simplex", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δₙ − (1,…,1)", "standard_concept": "the paper's extremal simplex", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue volume of K, as a real number (toReal; 0 if the volume is infinite)", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "The name says 'normalized', but this is plain Lebesgue volume. It is finite for compact K."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "vol(K)⁻¹ ∫_K x dx", "standard_concept": "barycenter (centroid)", "matches_standard": "yes", "note": "Junk values occur only when vol = 0 or the integral is not integrable. Both are excluded for compact sets with nonempty interior."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "{z ∈ ℤⁿ : z ∈ int K}", "standard_concept": "int(K) ∩ ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "a convex, compact set with nonempty interior, barycenter 0, and int ∩ ℤⁿ = {0}", "standard_concept": "convex body as in Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)ⁿ/n!", "standard_concept": "Ehrhart's sharp constant", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0 and S ⊂ ℝⁿ: if S is convex and compact, int S ≠ ∅, the barycenter of S is 0, and int S ∩ ℤⁿ = {0}, then vol(S) ≤ (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For all n, the barycenter of (n+1)Δₙ − (1,…,1) is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+1)Δₙ − (1,…,1)) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "Assuming 1 = 0 in ℕ (false), for n > 0 there is a centered body of volume (n+1)ⁿ/n!. The statement is vacuous."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "Let K ⊂ ℝⁿ be a full-dimensional compact convex body with barycenter 0 and int(K) ∩ ℤⁿ = {0}. Then vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark (after Thm 1.1)", "plain": "The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, has no interior lattice point other than 0, and has volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "The hypotheses and conclusion match. n > 0 is implicit in the paper."},
  {"paper_ref": "Sharpness remark (after Thm 1.1)", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "lean_weaker", "why": "The false hypothesis 1 = 0 makes the existence claim vacuous. The two separate simplex lemmas cover the barycenter and the volume, but not the lattice-point condition."}
 ],
