  {"id": "F2", "category": "coverage", "severity": "medium", "decl": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "paper_ref": "Sharpness remark (after Thm 1.1)", "explanation": "No target theorem asserts that the centered simplex is convex, compact, has nonempty interior, or satisfies int ∩ ℤⁿ = {0}. Sharpness of the bound is therefore not formally established.", "polarity": "lean weaker", "probe_idea": "theorem : ∀ n > 0, interiorLatticePoints (centeredSimplex n) = {0}"}
 ],
